// <auto-generated companion /> — mirrors Spark::SceneManager on a GameWorld.
#nullable enable

namespace Spark.Bindings;

/// <summary>Additive scene load/unload and prefab instantiation.</summary>
public sealed unsafe class WorldScenes : WorldFacet
{
    private SparkSceneManager* _manager;
    private bool _disposed;

    public WorldScenes(GameWorld world)
        : base(world) { }

    public uint LoadedSceneCount
    {
        get
        {
            unsafe
            {
                return Native.spark_scene_manager_get_loaded_scene_count(EnsureManager());
            }
        }
    }

    public SceneInstanceId LoadFromFile(string path, SceneLoadOptions? options = null)
    {
        unsafe
        {
            ulong id = 0;
            InteropUtf8.WithUtf8(path, pathPtr =>
            {
                var pathUtf8 = (sbyte*)pathPtr;
                id = InvokeWithOptions(options, nativeOptions =>
                    Native.spark_scene_manager_load_from_file(EnsureManager(), pathUtf8, nativeOptions));
            });
            return new SceneInstanceId(id);
        }
    }

    public SceneInstanceId BeginLoadAsync(string path, SceneLoadOptions? options = null)
    {
        unsafe
        {
            ulong id = 0;
            InteropUtf8.WithUtf8(path, pathPtr =>
            {
                var pathUtf8 = (sbyte*)pathPtr;
                id = InvokeWithOptions(options, nativeOptions =>
                    Native.spark_scene_manager_begin_load_async(EnsureManager(), pathUtf8, nativeOptions));
            });
            return new SceneInstanceId(id);
        }
    }

    public void Pump()
    {
        unsafe
        {
            Native.spark_scene_manager_pump(EnsureManager());
        }
    }

    public bool IsSceneReady(SceneInstanceId instanceId)
    {
        unsafe
        {
            return Native.spark_scene_manager_is_scene_ready(EnsureManager(), instanceId.Value) != 0;
        }
    }

    public bool HasSceneFailed(SceneInstanceId instanceId)
    {
        unsafe
        {
            return Native.spark_scene_manager_has_scene_failed(EnsureManager(), instanceId.Value) != 0;
        }
    }

    public void Unload(SceneInstanceId instanceId)
    {
        unsafe
        {
            Native.spark_scene_manager_unload_scene(EnsureManager(), instanceId.Value);
        }
    }

    public void UnloadAll()
    {
        unsafe
        {
            Native.spark_scene_manager_unload_all_scenes(EnsureManager());
        }
    }

    public (SceneInstanceId InstanceId, SceneSpawnPose Spawn) LoadAtSpawnPoint(
        string scenePath,
        string? spawnPointName = null,
        SceneLoadOptions? options = null)
    {
        unsafe
        {
            ulong id = 0;
            SceneSpawnPose spawn = default;
            InteropUtf8.WithUtf8(scenePath, scenePathPtr =>
            {
                InteropUtf8.WithUtf8(spawnPointName, spawnNamePtr =>
                {
                    SparkSceneSpawnPose nativePose = default;
                    id = LoadAtSpawnPointNative(
                        (sbyte*)scenePathPtr,
                        (sbyte*)spawnNamePtr,
                        options,
                        &nativePose);
                    spawn = ToSpawnPose(nativePose);
                });
            });
            return (new SceneInstanceId(id), spawn);
        }
    }

    public PrefabInstantiateResult InstantiatePrefab(
        string prefabPath,
        GameObject? parent = null,
        Vector3? position = null,
        Quaternion? rotation = null,
        string? assetsRoot = null,
        bool additive = true,
        bool pumpUntilReady = true,
        int maxRoots = 16)
    {
        unsafe
        {
            PrefabInstantiateResult result = default;
            InteropUtf8.WithUtf8(prefabPath, prefabPtr =>
            {
                InteropUtf8.WithUtf8(assetsRoot, assetsPtr =>
                {
                    SparkVector3 posNative = default;
                    SparkVector3* posPtr = null;
                    if (position is Vector3 p)
                    {
                        posNative = p.ToNative();
                        posPtr = &posNative;
                    }

                    SparkQuaternion rotNative = default;
                    SparkQuaternion* rotPtr = null;
                    if (rotation is Quaternion r)
                    {
                        rotNative = r.ToNative();
                        rotPtr = &rotNative;
                    }

                    var nativeRoots = stackalloc SparkGameObject*[maxRoots];
                    SparkPrefabInstantiateResult nativeResult = default;
                    Native.spark_scene_manager_instantiate_prefab(
                        EnsureManager(),
                        (sbyte*)prefabPtr,
                        parent == null ? null : InteropPtr.Object(parent.Handle),
                        posPtr,
                        rotPtr,
                        (sbyte*)assetsPtr,
                        additive ? 1 : 0,
                        pumpUntilReady ? 1 : 0,
                        &nativeResult,
                        nativeRoots,
                        (uint)maxRoots);

                    var roots = new GameObject[Math.Min((int)nativeResult.RootCount, maxRoots)];
                    for (int i = 0; i < roots.Length; i++)
                    {
                        roots[i] = new GameObject(InteropPtr.From(nativeRoots[i]));
                    }

                    result = new PrefabInstantiateResult
                    {
                        InstanceId = new SceneInstanceId(nativeResult.InstanceId),
                        Ready = nativeResult.Ready != 0,
                        RootObjects = roots,
                    };
                });
            });
            return result;
        }
    }

    ~WorldScenes()
    {
        DisposeNative();
    }

    private void DisposeNative()
    {
        if (_disposed)
        {
            return;
        }

        unsafe
        {
            if (_manager != null)
            {
                Native.spark_scene_manager_destroy(_manager);
                _manager = null;
            }
        }

        _disposed = true;
    }

    private unsafe SparkSceneManager* EnsureManager()
    {
        if (_manager == null)
        {
            _manager = Native.spark_scene_manager_create(InteropPtr.World(World.Handle));
        }

        return _manager;
    }

    private unsafe ulong LoadAtSpawnPointNative(
        sbyte* scenePath,
        sbyte* spawnPointName,
        SceneLoadOptions? options,
        SparkSceneSpawnPose* outSpawnPose)
    {
        if (options == null)
        {
            return Native.spark_scene_manager_load_at_spawn_point(
                EnsureManager(),
                scenePath,
                spawnPointName,
                outSpawnPose,
                null);
        }

        ulong id = 0;
        InteropUtf8.WithUtf8(options.AssetsRoot, assetsPtr =>
        {
            InteropUtf8.WithUtf8(options.SceneName, namePtr =>
            {
                var native = new SparkSceneLoadOptions
                {
                    AssetsRoot = (sbyte*)assetsPtr,
                    Additive = options.Additive ? 1 : 0,
                    SceneNameUtf8 = (sbyte*)namePtr,
                };
                id = Native.spark_scene_manager_load_at_spawn_point(
                    EnsureManager(),
                    scenePath,
                    spawnPointName,
                    outSpawnPose,
                    &native);
            });
        });
        return id;
    }

    private static SceneSpawnPose ToSpawnPose(SparkSceneSpawnPose nativePose)
        => new()
        {
            Found = nativePose.Found != 0,
            Position = Vector3.FromNative(nativePose.Position),
            Rotation = Quaternion.FromNative(nativePose.Rotation),
            SpawnObject = nativePose.SpawnObject == null
                ? null
                : new GameObject(InteropPtr.From(nativePose.SpawnObject)),
        };

    private static unsafe T InvokeWithOptions<T>(
        SceneLoadOptions? options,
        InvokeWithNativeOptions<T> invoke)
    {
        if (options == null)
        {
            return invoke(null);
        }

        T value = default!;
        InteropUtf8.WithUtf8(options.AssetsRoot, assetsPtr =>
        {
            InteropUtf8.WithUtf8(options.SceneName, namePtr =>
            {
                var native = new SparkSceneLoadOptions
                {
                    AssetsRoot = (sbyte*)assetsPtr,
                    Additive = options.Additive ? 1 : 0,
                    SceneNameUtf8 = (sbyte*)namePtr,
                };
                value = invoke(&native);
            });
        });
        return value;
    }

    private unsafe delegate T InvokeWithNativeOptions<T>(SparkSceneLoadOptions* nativeOptions);
}
